// Violates ISP: fat interface forces all implementors to handle everything
interface Worker {
    void work();
    void eat();
    void sleep();
    void attendMeeting();
}

class Robot implements Worker {
    public void work() { /* actual work */ }
    public void eat() { throw new UnsupportedOperationException("Robots don't eat"); }
    public void sleep() { throw new UnsupportedOperationException("Robots don't sleep"); }
    public void attendMeeting() { /* can do this */ }
}

// ISP-compliant: split into focused interfaces
interface Workable { void work(); }
interface Eatable { void eat(); }
interface Sleepable { void sleep(); }
interface Meetable { void attendMeeting(); }

class Human implements Workable, Eatable, Sleepable, Meetable {
    public void work() { /* work logic */ }
    public void eat() { /* eat logic */ }
    public void sleep() { /* sleep logic */ }
    public void attendMeeting() { /* meeting logic */ }
}

class RobotWorker implements Workable, Meetable {
    public void work() { /* work logic */ }
    public void attendMeeting() { /* meeting logic */ }
    // No forced eat() or sleep() methods
}

// Fat interface: covers persistence, validation, notifications, and reporting
interface CustomerService {
    void saveCustomer(Customer customer);
    void deleteCustomer(Long id);
    Customer findById(Long id);
    List<Customer> findAll();
    boolean validateEmail(String email);
    boolean validatePhoneNumber(String phone);
    void sendWelcomeEmail(Customer customer);
    void sendPromotionalEmail(Customer customer);
    List<Customer> generateMonthlyReport();
    byte[] exportCustomersToExcel();
}

// A read-only service is forced to implement write and notification methods
class ReadOnlyCustomerService implements CustomerService {
    public Customer findById(Long id) { /* actual logic */ }
    public List<Customer> findAll() { /* actual logic */ }

    // Forced to implement methods it does not need
    public void saveCustomer(Customer c) { throw new UnsupportedOperationException(); }
    public void deleteCustomer(Long id) { throw new UnsupportedOperationException(); }
    public boolean validateEmail(String e) { throw new UnsupportedOperationException(); }
    public boolean validatePhoneNumber(String p) { throw new UnsupportedOperationException(); }
    public void sendWelcomeEmail(Customer c) { throw new UnsupportedOperationException(); }
    public void sendPromotionalEmail(Customer c) { throw new UnsupportedOperationException(); }
    public List<Customer> generateMonthlyReport() { throw new UnsupportedOperationException(); }
    public byte[] exportCustomersToExcel() { throw new UnsupportedOperationException(); }
}

// Without ISP: fat interface used by many classes
interface PaymentProcessor {
    void processPayment(Payment payment);
    void refundPayment(Long paymentId);
    void generateInvoice(Long paymentId);  // New requirement added
}

// All 5 implementing classes must now implement generateInvoice
class CreditCardProcessor implements PaymentProcessor { /* must add generateInvoice */ }
class PayPalProcessor implements PaymentProcessor { /* must add generateInvoice */ }
class GiftCardProcessor implements PaymentProcessor { /* must add generateInvoice */ }
class CryptoProcessor implements PaymentProcessor { /* must add generateInvoice */ }
class BankTransferProcessor implements PaymentProcessor { /* must add generateInvoice */ }

// With ISP: focused interfaces
interface PaymentProcessor { void processPayment(Payment payment); }
interface RefundablePayment { void refundPayment(Long paymentId); }
interface InvoiceGenerator { void generateInvoice(Long paymentId); }  // New interface

// Only classes that need invoices implement InvoiceGenerator
class CreditCardProcessor implements PaymentProcessor, RefundablePayment, InvoiceGenerator {
    public void processPayment(Payment p) { /* logic */ }
    public void refundPayment(Long id) { /* logic */ }
    public void generateInvoice(Long id) { /* new logic */ }
}

// GiftCardProcessor is unaffected by the invoice feature
class GiftCardProcessor implements PaymentProcessor {
    public void processPayment(Payment p) { /* logic */ }
}

