interface CustomerQueries {
    Optional<CustomerView> findById(long id);
    List<CustomerView> findActive();
}

interface CustomerCommands {
    CustomerView create(CreateCustomer command);
    void deactivate(long id);
}

@RestController
final class CustomerReportController {
    private final CustomerQueries queries;

    CustomerReportController(CustomerQueries queries) {
        this.queries = queries;
    }

    @GetMapping("/customers/active")
    List<CustomerView> active() {
        return queries.findActive();
    }
}
```

The controller's Java contract contains no write operation. Authorization is still required because type shape alone cannot protect an HTTP endpoint.

